begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
grant usage on schema extensions to wedding_mutator;
select no_plan();
insert into auth.users(id,email) values('15000000-0000-4000-8000-000000000001','wp15-a@example.invalid'),('15000000-0000-4000-8000-000000000002','wp15-b@example.invalid');
create temporary table wp15(label text primary key,id uuid);
grant select,insert,update on wp15 to authenticated,wedding_mutator;
create temporary table wp15_before(version text,events bigint);
grant select,insert,update on wp15_before to authenticated;
create function pg_temp.cost_change(p_label text,op text,fields jsonb default '{}',confirmed boolean default false,reason text default null) returns jsonb language plpgsql security invoker as $f$ begin return public.finance_cost((select id from wp15 where label='a'),(select id from wp15 where label=p_label),(select state_version from public.weddings where id=(select id from wp15 where label='a')),op,fields,confirmed,reason);end;$f$;
create function pg_temp.cash_change(cost_label text,entry_label text,op text,fields jsonb default '{}',confirmed boolean default false,reason text default null) returns jsonb language plpgsql security invoker as $f$ begin return public.finance_cash((select id from wp15 where label='a'),(select id from wp15 where label=cost_label),(select id from wp15 where label=entry_label),(select state_version from public.weddings where id=(select id from wp15 where label='a')),op,fields,confirmed,reason);end;$f$;
select ok(to_regprocedure('public.finance_cost(uuid,uuid,text,text,jsonb,boolean,text)') is not null,'protected cost operation exists');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"15000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wp15 values('a',public.create_wedding('WP15 SQL synthetic','Test city'));
select public.save_draft_setup((select id from wp15 where label='a'),(select state_version from public.weddings),'WP15 SQL synthetic','Test city',null,true,null,'[{"title":"Reception"}]');
select public.generate_draft((select id from wp15 where label='a'),(select state_version from public.weddings));
select public.activate_plan((select id from wp15 where label='a'),(select state_version from public.weddings),true);
select lives_ok($$select pg_temp.cost_change(null,'create','{"title":"Shared unknown","ceremony_id":null,"pricing_basis":"FIXED","fixed_estimate_paise":null,"per_guest_rate_paise":null}')$$,'nullable shared estimate persisted');
insert into wp15 select 'main',id from public.cost_items where title='Shared unknown';
select is((select fixed_estimate_paise from public.cost_items where id=(select id from wp15 where label='main')),null::text,'unknown is not zero');
select throws_ok($$select pg_temp.cost_change('main','state','{"state":"COMMITTED","amount_paise":"20000000"}')$$,'22023',null,'state change requires confirmation');
select lives_ok($$select pg_temp.cost_change('main','state','{"state":"COMMITTED","amount_paise":"20000000"}',true)$$,'commit amount persisted');
select is((select commitment_paise from public.cost_items where id=(select id from wp15 where label='main')),'20000000','commitment exact text');
select is(jsonb_typeof(public.finance_read((select id from wp15 where label='a'))->'items'->0->'commitment_paise'),'string','snapshot money transport is text');
select lives_ok($$select pg_temp.cash_change('main',null,'post','{"kind":"PAYMENT","amount_paise":"5000000","occurred_on":"2026-10-27","note":null,"intent_key":"sql-payment-a"}')$$,'payment posted');
insert into wp15 select 'payment',id from public.cash_entries where intent_key='sql-payment-a';
insert into wp15_before select state_version,(select count(*) from public.audit_events) from public.weddings;
select lives_ok($$select public.finance_cash((select id from wp15 where label='a'),(select id from wp15 where label='main'),null,'0','post','{"kind":"PAYMENT","amount_paise":"5000000","occurred_on":"2026-10-27","note":null,"intent_key":"sql-payment-a"}',false,null)$$,'same intent stale-version retry returns existing result');
select is((select count(*) from public.cash_entries where intent_key='sql-payment-a'),1::bigint,'same intent one row');
select is((select state_version from public.weddings),(select version from wp15_before),'retry does not bump version');
select is((select count(*) from public.audit_events),(select events from wp15_before),'retry does not duplicate audit');
select throws_ok($$select pg_temp.cash_change('main',null,'post','{"kind":"PAYMENT","amount_paise":"1","occurred_on":"2026-10-27","note":null,"intent_key":"sql-payment-a"}')$$,'23514',null,'conflicting intent payload rejected');
select lives_ok($$select pg_temp.cash_change('main',null,'post','{"kind":"REFUND_RECEIVED","amount_paise":"2000000","occurred_on":"2026-10-27","note":null,"intent_key":"sql-refund-a"}')$$,'received refund recorded separately');
insert into wp15 select 'refund',id from public.cash_entries where intent_key='sql-refund-a';
update wp15_before set version=(select state_version from public.weddings),events=(select count(*) from public.audit_events);
select throws_ok($$select pg_temp.cash_change('main','payment','void','{}',true,'Wrong payment')$$,'23514',null,'payment void cannot strand refund');
select is((select state_version from public.weddings),(select version from wp15_before),'failed void version rollback');
select is((select count(*) from public.audit_events),(select events from wp15_before),'failed void audit rollback');
select is((select status from public.cash_entries where id=(select id from wp15 where label='payment')),'POSTED','failed void original still posted');
select lives_ok($$select pg_temp.cash_change('main','refund','void','{}',true,'Wrong refund')$$,'refund corrected first');
select lives_ok($$select pg_temp.cash_change('main','payment','void','{}',true,'Wrong payment')$$,'payment then safely voided');
select ok((select status='VOIDED' and amount_paise='5000000' and void_audit_event_id is not null from public.cash_entries where id=(select id from wp15 where label='payment')),'void retains amount/identity plus audit link');
select lives_ok($$select pg_temp.cash_change('main',null,'post','{"kind":"PAYMENT","amount_paise":"4000000","occurred_on":"2026-10-27","note":null,"intent_key":"corrected-payment"}')$$,'corrected replacement posted with new intent');
select is((select count(*) from public.cash_entries),3::bigint,'original and corrected records all retained');
select lives_ok($$select public.finance_cash((select id from wp15 where label='a'),(select id from wp15 where label='main'),null,'0','post','{"kind":"PAYMENT","amount_paise":"5000000","occurred_on":"2026-10-27","note":null,"intent_key":"sql-payment-a"}',false,null)$$,'retry voided original does not resurrect cash');
select is((select status from public.cash_entries where intent_key='sql-payment-a'),'VOIDED','voided status preserved');
select lives_ok($$select pg_temp.cost_change('main','state','{"state":"CANCELLED","amount_paise":null}',true)$$,'cancel with unknown settlement supported');
select is((select cancellation_settlement_paise from public.cost_items),null::text,'unknown cancellation settlement retained');
select lives_ok($$select pg_temp.cost_change('main','correct','{"amount_paise":"1500000"}',true,'Settlement confirmed')$$,'confirmed settlement recorded');
select lives_ok($$select pg_temp.cost_change('main','expected_refund','{"expected_refund_paise":"2500000"}')$$,'expected refund informational field');
select ok((select state='CANCELLED' and commitment_paise='20000000' and cancellation_settlement_paise='1500000' and expected_refund_paise='2500000' from public.cost_items),'cancel/re-read preserves original commitment and settlement');
select throws_ok($$select pg_temp.cost_change('main','state','{"state":"PLANNED","amount_paise":null}',true)$$,'23514',null,'cancelled cannot reverse');
select throws_ok($$select pg_temp.cost_change('main','edit','{"commitment_paise":"1"}')$$,'22023',null,'historical amount cannot use ordinary edit');
select throws_ok($$select pg_temp.cost_change('main','correct','{"amount_paise":"1"}',true,'')$$,'22023',null,'correction needs reason');
select throws_ok($$select pg_temp.cost_change('main','archive','{}',true)$$,'23514',null,'money/history cannot archive');
select lives_ok($$select pg_temp.cost_change(null,'create','{"title":"Empty planned archive","ceremony_id":null,"pricing_basis":"FIXED","fixed_estimate_paise":"0","per_guest_rate_paise":null}')$$,'known zero planned item');
insert into wp15 select 'archive',id from public.cost_items where title='Empty planned archive';
select lives_ok($$select pg_temp.cost_change('archive','archive','{}',true)$$,'creation audit does not prevent safe empty planned archive');
select throws_ok($$select pg_temp.cost_change('archive','edit','{"title":"Hidden rewrite"}')$$,'55000',null,'archived cost immutable');
select throws_ok($$select pg_temp.cash_change('archive',null,'post','{"kind":"PAYMENT","amount_paise":"1","occurred_on":"2026-10-27","note":null,"intent_key":"archived-pay"}')$$,'55000',null,'archived cash posting denied');
select lives_ok($$select pg_temp.cost_change(null,'create','{"title":"Equal payments","ceremony_id":null,"pricing_basis":"FIXED","fixed_estimate_paise":null,"per_guest_rate_paise":null}')$$,'second cash ledger');
insert into wp15 select 'equal',id from public.cost_items where title='Equal payments';
select pg_temp.cash_change('equal',null,'post','{"kind":"PAYMENT","amount_paise":"100","occurred_on":"2026-10-27","note":null,"intent_key":"equal-1"}');
select pg_temp.cash_change('equal',null,'post','{"kind":"PAYMENT","amount_paise":"100","occurred_on":"2026-10-27","note":null,"intent_key":"equal-2"}');
select is((select sum(amount_paise::bigint) from public.cash_entries where cost_item_id=(select id from wp15 where label='equal')),200::numeric,'intentional equal payments both count');
select throws_ok($$delete from wedding_private.cash_entries$$,'42501',null,'cash hard delete denied');
select throws_ok($$delete from wedding_private.cost_items$$,'42501',null,'cost hard delete denied');
select throws_ok($$update wedding_private.cash_entries set amount_paise=1$$,'42501',null,'ordinary cash update denied');
select ok(exists(select 1 from pg_constraint where conrelid='wedding_private.cash_entries'::regclass and confrelid='wedding_private.cost_items'::regclass and confdeltype='r'),'cash parent FK RESTRICT retained');
select ok(not has_function_privilege('anon','public.finance_cash(uuid,uuid,uuid,text,text,jsonb,boolean,text)','EXECUTE'),'anonymous cash RPC denied');
select set_config('request.jwt.claims','{"sub":"15000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.finance_read((select id from wp15 where label='a')),null::jsonb,'B snapshot cannot read A');
select throws_ok($$select public.finance_cost((select id from wp15 where label='a'),(select id from wp15 where label='main'),'0','correct','{"amount_paise":"1"}',true,'Forged')$$,'42501',null,'B cost mutation denied');
select throws_ok($$select public.finance_cash((select id from wp15 where label='a'),(select id from wp15 where label='main'),null,'0','post','{"kind":"PAYMENT","amount_paise":"1","occurred_on":"2026-10-27","note":null,"intent_key":"b-forgery"}',false,null)$$,'42501',null,'B cash mutation denied');
select is((select count(*) from public.cost_items),0::bigint,'B cost views empty for A');
select is((select count(*) from public.cash_entries),0::bigint,'B cash views empty for A');
insert into wp15 values('b',public.create_wedding('WP15 B synthetic','Test city'));
select public.save_draft_setup((select id from wp15 where label='b'),(select state_version from public.weddings),'WP15 B synthetic','Test city',null,true,null,'[{"title":"Reception"}]');
insert into wp15 select 'b-ceremony',id from public.ceremonies;
select public.generate_draft((select id from wp15 where label='b'),(select state_version from public.weddings));
select public.activate_plan((select id from wp15 where label='b'),(select state_version from public.weddings),true);
insert into wp15 select 'b-cost',(public.finance_cost((select id from wp15 where label='b'),null,(select state_version from public.weddings),'create','{"title":"B private cost","ceremony_id":null,"pricing_basis":"FIXED","fixed_estimate_paise":null,"per_guest_rate_paise":null}',false,null)->>'id')::uuid;
insert into wp15 select 'b-entry',(public.finance_cash((select id from wp15 where label='b'),(select id from wp15 where label='b-cost'),null,(select state_version from public.weddings),'post','{"kind":"PAYMENT","amount_paise":"1","occurred_on":"2026-10-27","intent_key":"b-private","note":null}',false,null)->>'id')::uuid;
select set_config('request.jwt.claims','{"sub":"15000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select pg_temp.cost_change('b-cost','edit','{"title":"Forged"}')$$,'42501',null,'existing B cost cannot be forged under A parent');
select throws_ok($$select pg_temp.cash_change('b-cost',null,'post','{"kind":"PAYMENT","amount_paise":"1","occurred_on":"2026-10-27","note":null,"intent_key":"forged-b-cost"}')$$,'42501',null,'existing B cost cash reference denied');
select throws_ok($$select pg_temp.cash_change('main','b-entry','void','{}',true,'Forged')$$,'42501',null,'existing B cash cannot be voided under A');
select throws_ok($$select pg_temp.cost_change(null,'create',jsonb_build_object('title','Forged ceremony','ceremony_id',(select id::text from wp15 where label='b-ceremony'),'pricing_basis','FIXED','fixed_estimate_paise',null,'per_guest_rate_paise',null))$$,'42501',null,'existing B ceremony cannot be used by A');
select lives_ok($$select pg_temp.cost_change('equal','state','{"state":"FINAL","amount_paise":"1000"}',true)$$,'final actual recorded');
select throws_ok($$select pg_temp.cost_change('equal','state','{"state":"CANCELLED","amount_paise":"0"}',true)$$,'23514',null,'FINAL cannot auto-cancel');
select lives_ok($$select pg_temp.cost_change('equal','correct','{"amount_paise":"900"}',true,'Actual corrected')$$,'owner-confirmed actual correction');
select ok(exists(select 1 from public.audit_events where entity_id=(select id from wp15 where label='equal') and action='COST_AMOUNT_CORRECTED' and before_after->'before'->>'actual_paise'='1000'),'prior actual retained in audit');
set local role wedding_mutator;
select throws_ok($$update wedding_private.cash_entries set amount_paise=1 where intent_key='corrected-payment'$$,'23514',null,'DB trigger protects posted cash payload');
select * from finish();
rollback;
